part of 'academy_english_advanced_models.dart';
abstract final class EnglishAdvancedCoreLessons {
  static const lessons = <EnglishAdvancedLesson>[
    EnglishAdvancedLesson(level:"A2",number:1,title:"The Train Ticket",titleArabic:"تذكرة القطار",storyTitle:"The Train Ticket",storyTitleArabic:"تذكرة القطار",paragraphs:<String>["At the busy station, Lina checked the departure schedule and hurried towards platform four. Her suitcase was heavy, and she could not find her ticket. The long queue at the desk made her worried because the train was leaving soon.","She asked the clerk for help. He checked her booking receipt and showed her the correct carriage. Lina opened her bag once more and discovered the missing ticket inside a small pocket. She smiled and thanked the clerk.","Later, she told her sister about her journey. She explained that asking for help was better than panicking and that a small problem could teach a useful lesson. Next time, she would check her documents before leaving home."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("station","محطة"),EnglishAdvancedWord("departure","مغادرة"),EnglishAdvancedWord("schedule","جدول"),EnglishAdvancedWord("platform","رصيف"),EnglishAdvancedWord("suitcase","حقيبة سفر"),EnglishAdvancedWord("ticket","تذكرة"),EnglishAdvancedWord("queue","طابور"),EnglishAdvancedWord("clerk","موظف"),EnglishAdvancedWord("booking","حجز"),EnglishAdvancedWord("receipt","إيصال")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("carriage","عربة قطار"),EnglishAdvancedWord("arrival","وصول"),EnglishAdvancedWord("passport","جواز سفر"),EnglishAdvancedWord("luggage","أمتعة"),EnglishAdvancedWord("delay","تأخير"),EnglishAdvancedWord("destination","وجهة"),EnglishAdvancedWord("reservation","حجز مسبق"),EnglishAdvancedWord("information desk","مكتب استعلامات"),EnglishAdvancedWord("return journey","رحلة العودة"),EnglishAdvancedWord("boarding","صعود الطائرة أو القطار"),EnglishAdvancedWord("fare","أجرة"),EnglishAdvancedWord("traveler","مسافر"),EnglishAdvancedWord("connection","رحلة مواصلة"),EnglishAdvancedWord("timetable","جدول مواقيت"),EnglishAdvancedWord("transfer","انتقال"),EnglishAdvancedWord("departure gate","بوابة المغادرة")],grammarTitle:"Past simple and completed actions",grammarArabic:"نستخدم الماضي البسيط عندما نصف أحداثًا مكتملة. نضيف ed إلى كثير من الأفعال المنتظمة مثل checked وasked. في السؤال نستخدم Did ثم الفعل في صورته الأساسية.",grammarExamples:<String>["Lina checked the schedule.","Did she find her ticket?","She asked for help."],listening:"Attention, passengers traveling to Bristol. Your train will now depart from platform six at ten thirty, rather than platform four. Please check your ticket and allow extra time to reach the correct carriage. If you need assistance, ask the station clerk before boarding. The journey is expected to take ninety minutes.",listeningQuestion:"What has changed about the Bristol service?",listeningOptions:<String>["The platform","The destination","The ticket price"],listeningAnswer:0,readingQuestion:"Where did Lina discover her ticket?",readingOptions:<String>["At the help desk","In a pocket of her bag","In the carriage"],readingAnswer:1,writingCue:"Lina showed the clerk her booking ____.",writingAnswer:"receipt"),
    EnglishAdvancedLesson(level:"B1",number:1,title:"The Library That Almost Closed",titleArabic:"المكتبة التي كادت تغلق",storyTitle:"The Library That Almost Closed",storyTitleArabic:"المكتبة التي كادت تغلق",paragraphs:<String>["The town library had served local families for generations, but a funding cut threatened its future. Nadia, a volunteer, called a meeting with an organizer and several teachers. She asked everyone to bring a practical proposal rather than simply complain.","They discussed the budget, the venue and a difficult deadline. Someone suggested a fundraiser with musicians, while another person promised to find a sponsor. Nadia prepared an invitation explaining why the library mattered to children and older residents.","A storm forced them to postpone the outdoor concert, and the group began to worry. Nadia did not give up. She asked the volunteers to move everything indoors and invited neighbors through a community website.","By Sunday evening, the donations were sufficient to protect the library for another year. Their achievement was not only financial. People who had rarely spoken to each other now knew how to cooperate when their community needed them."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("library","مكتبة"),EnglishAdvancedWord("funding cut","خفض تمويل"),EnglishAdvancedWord("volunteer","متطوع"),EnglishAdvancedWord("organizer","منظم"),EnglishAdvancedWord("proposal","مقترح"),EnglishAdvancedWord("budget","ميزانية"),EnglishAdvancedWord("venue","مكان الفعالية"),EnglishAdvancedWord("deadline","موعد نهائي"),EnglishAdvancedWord("fundraiser","حملة تبرعات"),EnglishAdvancedWord("sponsor","جهة راعية"),EnglishAdvancedWord("invitation","دعوة"),EnglishAdvancedWord("postpone","يؤجل")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("achievement","إنجاز"),EnglishAdvancedWord("campaign","حملة"),EnglishAdvancedWord("committee","لجنة"),EnglishAdvancedWord("contribution","مساهمة"),EnglishAdvancedWord("resources","موارد"),EnglishAdvancedWord("negotiate","يتفاوض"),EnglishAdvancedWord("attendance","حضور"),EnglishAdvancedWord("publicity","دعاية"),EnglishAdvancedWord("permit","تصريح"),EnglishAdvancedWord("estimate","تقدير"),EnglishAdvancedWord("partnership","شراكة"),EnglishAdvancedWord("commitment","التزام"),EnglishAdvancedWord("shortfall","عجز"),EnglishAdvancedWord("priority","أولوية"),EnglishAdvancedWord("outcome","نتيجة"),EnglishAdvancedWord("motivation","دافع"),EnglishAdvancedWord("coordination","تنسيق"),EnglishAdvancedWord("funding proposal","مقترح تمويل"),EnglishAdvancedWord("local residents","سكان محليون"),EnglishAdvancedWord("public benefit","منفعة عامة")],grammarTitle:"First conditional",grammarArabic:"نستخدم الشرط الأول للتحدث عن احتمال واقعي ونتيجته: If we raise enough money, the library will stay open. يأتي المضارع بعد if، ثم will والفعل الأساسي في جملة النتيجة.",grammarExamples:<String>["If we find a sponsor, we will buy new books.","We will postpone the event if it rains.","Unless people help, the library may close."],listening:"The council will review the library's financial position on Thursday. Residents who want to speak must register by Wednesday afternoon. The council is asking for evidence of the library's use as well as a realistic long-term funding plan. A large donation would help with immediate costs, but the committee says that ongoing volunteer support will be just as important. Nadia has asked all volunteers to send their attendance reports before the meeting.",listeningQuestion:"What does the council require in addition to donations?",listeningOptions:<String>["Proof of usage and future planning","An immediate closure","A new library building"],listeningAnswer:0,readingQuestion:"How did Nadia respond when the storm disrupted the concert?",readingOptions:<String>["She abandoned the fundraiser","She moved the concert inside","She postponed it for a year"],readingAnswer:1,writingCue:"The storm forced them to ____ the outdoor concert.",writingAnswer:"postpone"),
    EnglishAdvancedLesson(level:"B2",number:1,title:"The Headline That Spread",titleArabic:"العنوان الذي انتشر",storyTitle:"The Headline That Spread",storyTitleArabic:"العنوان الذي انتشر",paragraphs:<String>["A sensational headline claiming a collapse in school performance spread rapidly online. Readers drew a worrying implication from a graph, although the original report included an important qualification that the newspaper had omitted. Few people checked the source.","A junior journalist found the comparison misleading. The study's sample included different age groups across two years, and the graphical scale exaggerated the apparent decline. She requested the original dataset and asked a statistician for clarification before confronting her editor.","The editor faced an ethical dilemma. Publishing a correction could temporarily damage the newspaper's credibility, but remaining silent would allow misinformation to spread. The newsroom reviewed its procedures and decided to publish a transparent explanation rather than quietly changing the figures.","The correction received less attention than the first headline. Nevertheless, the journalist insisted that verification mattered more than popularity. She wrote a guide showing how a carefully chosen scale or incomplete comparison can distort what readers believe about complex evidence."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("sensational","مثير مبالغ فيه"),EnglishAdvancedWord("headline","عنوان خبري"),EnglishAdvancedWord("implication","دلالة ضمنية"),EnglishAdvancedWord("graph","رسم بياني"),EnglishAdvancedWord("qualification","تحفظ توضيحي"),EnglishAdvancedWord("source","مصدر"),EnglishAdvancedWord("misleading","مضلل"),EnglishAdvancedWord("sample","عينة"),EnglishAdvancedWord("graphical scale","مقياس الرسم"),EnglishAdvancedWord("dataset","مجموعة بيانات"),EnglishAdvancedWord("statistician","إحصائي"),EnglishAdvancedWord("clarification","توضيح"),EnglishAdvancedWord("correction","تصحيح"),EnglishAdvancedWord("credibility","مصداقية")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("misinformation","معلومات مضللة"),EnglishAdvancedWord("verification","تحقق"),EnglishAdvancedWord("journalistic ethics","أخلاق الصحافة"),EnglishAdvancedWord("source attribution","نسب المصدر"),EnglishAdvancedWord("editorial judgment","حكم تحريري"),EnglishAdvancedWord("peer review","مراجعة الأقران"),EnglishAdvancedWord("distortion","تشويه"),EnglishAdvancedWord("contextualize","يضع في السياق"),EnglishAdvancedWord("fact-checking","تقصي الحقائق"),EnglishAdvancedWord("disclosure","إفصاح"),EnglishAdvancedWord("transparency","شفافية"),EnglishAdvancedWord("retraction","سحب منشور"),EnglishAdvancedWord("exaggeration","مبالغة"),EnglishAdvancedWord("correlation","ارتباط"),EnglishAdvancedWord("causation","سببية"),EnglishAdvancedWord("outlier","قيمة شاذة"),EnglishAdvancedWord("methodology","منهجية"),EnglishAdvancedWord("survey bias","تحيز العينة"),EnglishAdvancedWord("media literacy","ثقافة إعلامية"),EnglishAdvancedWord("manipulation","تلاعب"),EnglishAdvancedWord("interpretation","تفسير"),EnglishAdvancedWord("editorial independence","استقلال تحريري"),EnglishAdvancedWord("selective reporting","انتقائية الإبلاغ"),EnglishAdvancedWord("publication standards","معايير النشر")],grammarTitle:"Passive voice and cautious reporting",grammarArabic:"نستخدم المبني للمجهول عندما نهتم بالحدث أكثر من فاعله: The report was published. ولعرض ما لم يُؤكد بعد نستخدم reportedly أو may have بدل الجزم بمعلومة مشكوك فيها.",grammarExamples:<String>["The original chart was shared without context.","The figures may have been misinterpreted.","The claim was reportedly corrected."],listening:"The editor explained that the numbers reported in the first article had not been fabricated, but their presentation lacked essential context. The distinction was crucial: readers were misled by a comparison that implied a stronger conclusion than the data justified. Although she accepted responsibility for the editorial decision, she rejected requests to erase the original story completely. A visible correction, she argued, would allow the public to examine both the mistake and its explanation. The newsroom also promised to change its verification process before publishing future statistical claims.",listeningQuestion:"Why was the original report misleading despite using real numbers?",listeningOptions:<String>["The numbers concerned another country","Their context and comparison distorted the conclusion","The journalist invented a new survey"],listeningAnswer:1,readingQuestion:"Why did the editor publish a visible correction?",readingOptions:<String>["To explain the mistake transparently","To hide the earlier article","To replace all school examinations"],readingAnswer:0,writingCue:"The journalist consulted a ____ to review the numbers.",writingAnswer:"statistician")
  ];
}
